class Solution:
    def findMinimumTime(self, strength: List[int]) -> int:
        n = len(strength); N = 2 * n + 2; S, T = N - 2, N - 1
        g = [[] for _ in range(N)]
        def add(u, v, c, w):
            g[u].append([v, c, w, len(g[v])])
            g[v].append([u, 0, -w, len(g[u]) - 1])
        for i in range(n):
            add(S, i, 1, 0); add(n + i, T, 1, 0)
            for j in range(n):
                add(i, n + j, 1, (strength[i] + j) // (j + 1))
        cost = 0
        for _ in range(n):
            INF = float('inf')
            dist = [INF] * N; dist[S] = 0; pe = [None] * N; inq = [False] * N
            dq = [S]; inq[S] = True
            while dq:
                u = dq.pop(); inq[u] = False
                for ei, e in enumerate(g[u]):
                    if e[1] > 0 and dist[u] + e[2] < dist[e[0]]:
                        dist[e[0]] = dist[u] + e[2]; pe[e[0]] = (u, ei)
                        if not inq[e[0]]: inq[e[0]] = True; dq.append(e[0])
            cost += dist[T]
            v = T
            while v != S:
                u, ei = pe[v]
                g[u][ei][1] -= 1; g[v][g[u][ei][3]][1] += 1; v = u
        return cost

