class Solution {
public:
    int findMinimumTime(vector<int>& strength) {
        int n = strength.size(), N = 2 * n + 2, S = N - 2, T = N - 1;
        struct E { int to, cap, w, next; };
        vector<vector<E>> g(N);
        auto add = [&](int u, int v, int c, int w) {
            g[u].push_back({v, c, w, (int)g[v].size()});
            g[v].push_back({u, 0, -w, (int)g[u].size() - 1});
        };
        for (int i = 0; i < n; i++) {
            add(S, i, 1, 0); add(n + i, T, 1, 0);
            for (int j = 0; j < n; j++) add(i, n + j, 1, (strength[i] + j) / (j + 1));
        }
        long long cost = 0;
        for (int it = 0; it < n; it++) {
            vector<long long> dist(N, LLONG_MAX); dist[S] = 0;
            vector<pair<int,int>> pe(N); vector<bool> inq(N, false);
            deque<int> dq; dq.push_back(S); inq[S] = true;
            while (!dq.empty()) {
                int u = dq.front(); dq.pop_front(); inq[u] = false;
                for (int ei = 0; ei < (int)g[u].size(); ei++) {
                    auto& e = g[u][ei];
                    if (e.cap > 0 && dist[u] + e.w < dist[e.to]) {
                        dist[e.to] = dist[u] + e.w; pe[e.to] = {u, ei};
                        if (!inq[e.to]) { inq[e.to] = true; dq.push_back(e.to); }
                    }
                }
            }
            cost += dist[T];
            int v = T;
            while (v != S) {
                auto [u, ei] = pe[v];
                g[u][ei].cap--; g[v][g[u][ei].next].cap++; v = u;
            }
        }
        return (int)cost;
    }
};

