class Solution {
    public int findMinimumTime(List<Integer> strength) {
        int n = strength.size(), N = 2 * n + 2, S = N - 2, T = N - 1;
        List<List<long[]>> g = new ArrayList<>();
        for (int i = 0; i < N; i++) g.add(newArrayList());
        for (int i = 0; i < n; i++) {
            add(g, S, i, 1, 0); add(g, n + i, T, 1, 0);
            for (int j = 0; j < n; j++) add(g, i, n + j, 1, (strength.get(i) + j) / (j + 1));
        }
        long cost = 0;
        for (int it = 0; it < n; it++) {
            long[] dist = new long[N]; Arrays.fill(dist, Long.MAX_VALUE); dist[S] = 0;
            int[][] pe = new int[N][]; boolean[] inq = new boolean[N];
            Deque<Integer> dq = new ArrayDeque<>(); dq.add(S); inq[S] = true;
            while (!dq.isEmpty()) {
                int u = dq.poll(); inq[u] = false;
                for (int ei = 0; ei < g.get(u).size(); ei++) {
                    long[] e = g.get(u).get(ei);
                    int v = (int) e[0];
                    if (e[1] > 0 && dist[u] + e[2] < dist[v]) {
                        dist[v] = dist[u] + e[2]; pe[v] = new int[]{u, ei};
                        if (!inq[v]) { inq[v] = true; dq.add(v); }
                    }
                }
            }
            cost += dist[T];
            int v = T;
            while (v != S) {
                int u = pe[v][0], ei = pe[v][1];
                g.get(u).get(ei)[1]--; g.get(v).get((int) g.get(u).get(ei)[3])[1]++; v = u;
            }
        }
        return (int) cost;
    }
    private List<long[]> newArrayList() { return new ArrayList<>(); }
    private void add(List<List<long[]>> g, int u, int v, int c, int w) {
        g.get(u).add(new long[]{v, c, w, g.get(v).size()});
        g.get(v).add(new long[]{u, 0, -w, g.get(u).size() - 1});
    }
}

