var findMinimumTime = function(strength) {
    const n = strength.length, N = 2 * n + 2, S = N - 2, T = N - 1;
    const g = Array.from({length: N}, () => []);
    const add = (u, v, c, w) => {
        g[u].push([v, c, w, g[v].length]);
        g[v].push([u, 0, -w, g[u].length - 1]);
    };
    for (let i = 0; i < n; i++) {
        add(S, i, 1, 0); add(n + i, T, 1, 0);
        for (let j = 0; j < n; j++) add(i, n + j, 1, Math.floor((strength[i] + j) / (j + 1)));
    }
    let cost = 0;
    for (let it = 0; it < n; it++) {
        const dist = Array(N).fill(Infinity); dist[S] = 0;
        const pe = Array(N), inq = Array(N).fill(false);
        const dq = [S]; inq[S] = true;
        while (dq.length) {
            const u = dq.pop(); inq[u] = false;
            for (let ei = 0; ei < g[u].length; ei++) {
                const e = g[u][ei];
                if (e[1] > 0 && dist[u] + e[2] < dist[e[0]]) {
                    dist[e[0]] = dist[u] + e[2]; pe[e[0]] = [u, ei];
                    if (!inq[e[0]]) { inq[e[0]] = true; dq.push(e[0]); }
                }
            }
        }
        cost += dist[T];
        let v = T;
        while (v !== S) {
            const [u, ei] = pe[v];
            g[u][ei][1]--; g[v][g[u][ei][3]][1]++; v = u;
        }
    }
    return cost;
};
